/* Original 곡선 🧭; keep every scalar span and CRLF. */
@model complete_original_curve_file {version:0;length-unit:mm;
/* This earlier Curve has similar numbers. It is not the target. */
@curve #context_curve {type:nurbs;degree:1;knots:[-0,-0,1,1];control-points:[[+0.00,-0,0],[2,0,1]];weights:[1.000,1];}
@curve #target_curve {type:nurbs;degree:4;knots:[-3,-3,-3,-3,-3,7,7,7,7,7];control-points:[[+0.000,-0,0],[2,1,0],[4,3,2],[6,-1,3],[8,0,4]];weights:[1.0000,2,0.5,1.5,1];}
@surface #context_plane {type:nurbs;degree-u:1;degree-v:1;knots-u:[0,0,1,1];knots-v:[0,0,1,1];control-points:[[[0,20,-0],[0,22,0]],[[2,20,0],[2,22,0]]];weights:[[1,1],[1,1]];}
}
/* Trailing notes: 보존. */
